  const auto report=files.filePath("values.csv");QString original=spec["script"].toString();for(const auto &p:QList<QPair<QString,QString>>{{"@SPEED@",QString::number(speed,'g',17)},{"@VALUES@",report},{"@EXTRA@",files.filePath("extra.csv")},{"@DC@",files.filePath("dc.txt")},{"@OPT@",files.filePath("opt.txt")}})original.replace(p.first,p.second);require(!original.contains('@'),"Unresolved fixture input");
  test.script->setPlainText(original);require(test.window.buildScript(),"Original structural Build failed");
