   const auto current=test.window.missionSnapshot();const auto probe=current.nodes[test.index("StructuralProbe")];const auto selectedNow=current.nodes[index()];const QString actualParent=probe.parent<0?"Root":current.nodes[probe.parent].type,actualLabel=probe.parent<0?QString():missionCommandLabel(current.nodes[probe.parent].statement).name;
