   insertions.append(QJsonObject{{"side",side},{"parent_type",actualParent},{"parent_label",actualLabel}});test.close();test.script->undo();require(test.script->toPlainText()==original&&test.window.buildScript(),"Insertion Undo failed");test.script->redo();require(test.script->toPlainText()==actual&&test.window.buildScript(),"Insertion Redo failed");test.script->undo();require(test.script->toPlainText()==original&&test.window.buildScript(),"Insertion restore failed");operations.append("insert-"+side);
